insert into public.programs
    (slug, name, organization, summary, criteria, required_documents, how_to_apply, official_url, source_label, sort_order)
values
    ('credit-maintien-domicile-aines', 'Crédit d’impôt pour maintien à domicile des aînés', 'Revenu Québec', 'Crédit d’impôt remboursable qui rembourse une partie des dépenses pour des services qui aident une personne de 70 ans ou plus à rester chez elle : entretien ménager, aide à la personne, préparation de repas, surveillance, ou la part du loyer d’une résidence privée pour aînés qui correspond à ces services. Il peut être versé d’avance, chaque mois.', '{"all":[{"fact":"recipient_age","op":">=","value":70,"label":"La personne a 70 ans ou plus"},{"fact":"living_setting","op":"in","value":["home","rpa"],"label":"Elle vit chez elle ou en résidence privée pour aînés"},{"fact":"pays_home_support_services","op":"==","value":true,"label":"Elle paie des services qui l’aident à rester chez elle"}]}'::jsonb, '["Factures ou reçus des services payés","Bail de la résidence et son annexe sur les services, s’il y a lieu"]'::jsonb, 'Dans la déclaration de revenus du Québec (annexe J), ou par versements anticipés, en faisant une demande à Revenu Québec.', 'https://www.revenuquebec.ca/fr/citoyens/credits-dimpot/credit-dimpot-pour-maintien-a-domicile/', 'Revenu Québec — Crédit d’impôt pour maintien à domicile des aînés', 10),
    ('credit-personne-aidante', 'Crédit d’impôt pour personne aidante', 'Revenu Québec', 'Crédit d’impôt remboursable pour la personne qui aide un proche : un adulte qui a une déficience grave et prolongée (même sans habiter avec lui), ou un proche de 70 ans ou plus qu’elle héberge ou avec qui elle habite. L’aide doit avoir duré au moins 365 jours consécutifs. Plusieurs personnes aidantes peuvent se partager le crédit.', '{"any":[{"fact":"severe_prolonged_impairment","op":"==","value":true,"label":"La personne a une déficience grave et prolongée (attestation requise)"},{"all":[{"fact":"recipient_age","op":">=","value":70,"label":"La personne a 70 ans ou plus"},{"fact":"caregiver_cohabits","op":"==","value":true,"label":"Vous habitez avec elle"}]}]}'::jsonb, '["Attestation de déficience (formulaire TP-752.0.14), remplie par un professionnel de la santé, si la personne a une déficience","Annexe H de la déclaration de revenus du Québec"]'::jsonb, 'Dans la déclaration de revenus du Québec, avec l’annexe H. Une partie peut être versée d’avance chaque mois : demande dans Mon dossier ou par formulaire.', 'https://www.revenuquebec.ca/fr/citoyens/credits-dimpot/credit-dimpot-pour-personne-aidante/conditions-dadmissibilite-de-base/', 'Revenu Québec — Crédit d’impôt pour personne aidante', 20),
    ('pefsad-aide-domestique', 'Programme d’exonération financière pour les services d’aide domestique (PEFSAD)', 'Régie de l’assurance maladie du Québec (RAMQ)', 'Réduit le tarif horaire des services d’aide domestique (ménage, entretien des vêtements, préparation de repas, courses) offerts par une entreprise d’économie sociale reconnue. Une aide de base s’applique à toute personne de 18 ans ou plus ; une aide supplémentaire dépend du revenu et de la situation, notamment à 65 ans ou plus.', '{"all":[{"fact":"living_setting","op":"in","value":["home","rpa"],"label":"Elle vit chez elle ou en résidence privée pour aînés"},{"fact":"domestic_help","op":"==","value":true,"label":"Elle reçoit, ou aimerait recevoir, de l’aide domestique (ménage, repas, courses)"}]}'::jsonb, '["Carte d’assurance maladie","Formulaire de demande remis par l’entreprise d’économie sociale"]'::jsonb, 'Communiquer avec une entreprise d’économie sociale en aide domestique reconnue : elle remet le formulaire et le transmet à la RAMQ.', 'https://www.ramq.gouv.qc.ca/sites/default/files/documents/depl-aide-domestique-fr.5.2.pdf', 'RAMQ — Programme d’exonération financière pour les services d’aide domestique (dépliant)', 30),
    ('montant-canadien-aidant-naturel', 'Montant canadien pour aidant naturel', 'Agence du revenu du Canada', 'Montant d’impôt fédéral pour la personne qui soutient un proche à sa charge ayant une déficience des fonctions physiques ou mentales. Il se demande dans la déclaration de revenus fédérale. Le montant accordé diminue selon le revenu de la personne aidée.', '{"all":[{"fact":"impairment_dependency","op":"==","value":true,"label":"La personne dépend de vous à cause d’une déficience physique ou mentale"}]}'::jsonb, '["Une attestation signée par un professionnel de la santé peut être demandée par l’Agence du revenu du Canada"]'::jsonb, 'Dans la déclaration de revenus fédérale, aux lignes indiquées par l’Agence du revenu du Canada.', 'https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/about-your-tax-return/tax-return/completing-a-tax-return/deductions-credits-expenses/canada-caregiver-amount.html', 'Agence du revenu du Canada — Montant canadien pour aidant naturel', 40),
    ('credit-impot-personnes-handicapees', 'Crédit d’impôt pour personnes handicapées (CIPH)', 'Agence du revenu du Canada', 'Crédit d’impôt fédéral pour une personne qui a une déficience grave et prolongée (au moins 12 mois) des fonctions physiques ou mentales, qui la limite de façon marquée dans les activités de la vie quotidienne. L’admissibilité dépend des effets de la déficience, pas du diagnostic. La part non utilisée peut parfois être transférée à un proche qui la soutient.', '{"all":[{"fact":"severe_prolonged_impairment","op":"==","value":true,"label":"Déficience grave et prolongée qui limite de façon marquée la vie quotidienne, attestée par un professionnel"}]}'::jsonb, '["Formulaire T2201 : partie A remplie par la personne ou son représentant, partie B remplie par un professionnel de la santé"]'::jsonb, 'Envoyer le formulaire T2201 complet à l’Agence du revenu du Canada, en ligne ou par la poste. Une fois approuvé, il n’est généralement pas nécessaire de le renvoyer chaque année.', 'https://www.canada.ca/credit-impot-personnes-handicapees', 'Agence du revenu du Canada — Crédit d’impôt pour personnes handicapées', 50),
    ('programme-adaptation-domicile', 'Programme d’adaptation de domicile (PAD)', 'Société d’habitation du Québec', 'Aide financière pour adapter le logement d’une personne handicapée afin qu’elle puisse y entrer, en sortir, accéder aux pièces essentielles et faire ses activités quotidiennes en sécurité. Selon l’option, un ergothérapeute évalue les besoins. À Montréal, la Ville gère sa propre version du programme.', '{"all":[{"fact":"needs_home_adaptation","op":"==","value":true,"label":"Son logement a besoin d’être adapté"},{"fact":"living_setting","op":"in","value":["home"],"label":"Elle vit dans son propre logement (pas en résidence ni en CHSLD)"},{"fact":"severe_prolonged_impairment","op":"==","value":true,"label":"Son incapacité est importante et persistante (preuve requise)"}]}'::jsonb, '["Preuve que l’incapacité est importante et persistante","Preuve de citoyenneté canadienne ou de résidence permanente"]'::jsonb, 'Selon l’option : auprès de la municipalité ou de la MRC (avec accompagnement d’un ergothérapeute), ou auprès de la Société d’habitation du Québec.', 'https://www.habitation.gouv.qc.ca/programme/programme/programme-dadaptation-de-domicile', 'Société d’habitation du Québec — Programme d’adaptation de domicile', 60),
    ('soutien-domicile-clsc', 'Services de soutien à domicile du CLSC', 'CLSC (réseau de la santé et des services sociaux)', 'Aide personnelle, aide domestique et répit pour la personne proche aidante, selon les besoins évalués par un intervenant du CLSC. La demande peut être faite en tout temps ; si les besoins changent, on peut demander une nouvelle évaluation. Une allocation pour payer soi-même certains services (allocation autonomie à domicile) peut être offerte.', '{"all":[{"fact":"living_setting","op":"in","value":["home","rpa"],"label":"Elle vit chez elle ou en résidence privée pour aînés"}]}'::jsonb, '["Carte d’assurance maladie de la personne aidée"]'::jsonb, 'Appeler le CLSC du secteur de la personne aidée et demander une évaluation pour le soutien à domicile. Services Québec peut donner les coordonnées du CLSC.', 'https://www.quebec.ca/famille-et-soutien-aux-personnes/inaptitude-perte-autonomie/services-soutien-domicile', 'Québec.ca — Services de soutien à domicile', 70),
    ('lappui-info-aidant-repit', 'Info-aidant et répit (L’Appui)', 'L’Appui pour les proches aidants', 'Info-aidant est un service téléphonique gratuit et confidentiel d’écoute, d’information et de références pour les personnes proches aidantes. Le répertoire de L’Appui aide à trouver des services de répit et de soutien près de chez vous.', '{"all":[{"fact":"is_caregiver","op":"==","value":true,"label":"Vous aidez un proche"}]}'::jsonb, '[]'::jsonb, 'Appeler Info-aidant (numéro dans « Aide immédiate », section des proches aidants) ou consulter le répertoire en ligne de L’Appui.', 'https://www.lappui.org/', 'L’Appui pour les proches aidants', 80)
